183	/** Keeps the reservations in the database. */
184	public final class ReservationStore {
185	
186	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
187	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
188	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
189	    private static final String EXCLUSION_VIOLATION = "23P01";
190	
191	    private final DataSource dataSource;
192	
193	    public ReservationStore(DataSource dataSource) {
194	        this.dataSource = dataSource;
195	    }
196	
197	    /** Saves a new reservation; the database numbers it. */
198	    Reservation add(NewReservation request, Price price) {
199	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
200	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
201	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
202	        try (Connection connection = dataSource.getConnection();
203	                PreparedStatement statement = connection.prepareStatement(insert)) {
204	            statement.setInt(1, request.roomNumber());
205	            statement.setString(2, request.guest().name());
206	            statement.setString(3, request.guest().email());
207	            statement.setString(4, request.guest().cpf());
208	            statement.setDate(5, Date.valueOf(request.checkIn()));
209	            statement.setDate(6, Date.valueOf(request.checkOut()));
210	            statement.setInt(7, request.guests());
211	            statement.setString(8, request.ratePlan().name());
212	            statement.setInt(9, price.nights());
213	            statement.setBigDecimal(10, price.subtotal());
214	            statement.setBigDecimal(11, price.discount());
215	            statement.setBigDecimal(12, price.total());
216	            statement.setString(13, ReservationStatus.PENDING.name());
217	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
218	            try (ResultSet generated = statement.executeQuery()) {
219	                generated.next();
220	                return new Reservation(generated.getLong("id"), request, price);
221	            }
222	        } catch (SQLException failure) {
223	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
224	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
225	                        "room " + request.roomNumber() + " is taken on some of those nights");
226	            }
227	            throw new IllegalStateException("could not save the reservation", failure);
228	        }
229	    }
230	
231	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
232	    void update(Reservation reservation) {
233	        try (Connection connection = dataSource.getConnection();
234	                PreparedStatement statement = connection.prepareStatement(
235	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
236	            statement.setString(1, reservation.status().name());
237	            statement.setBigDecimal(2, reservation.amountPaid());
238	            statement.setBigDecimal(3, reservation.refund());
239	            statement.setLong(4, reservation.id());
240	            statement.executeUpdate();
241	        } catch (SQLException failure) {
242	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
243	        }
244	    }
245	
246	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
247	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
248	        try (Connection connection = dataSource.getConnection();
249	                PreparedStatement select = connection.prepareStatement(
250	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
251	                                + "AND check_in < ? AND ? < check_out")) {
252	            select.setInt(1, roomNumber);
253	            select.setDate(2, Date.valueOf(checkOut));
254	            select.setDate(3, Date.valueOf(checkIn));
255	            try (ResultSet rows = select.executeQuery()) {
256	                return rows.next();
257	            }
258	        } catch (SQLException failure) {
259	            throw new IllegalStateException("could not check room " + roomNumber, failure);
260	        }
261	    }
262	
263	    public Optional<Reservation> find(long id) {
264	        try (Connection connection = dataSource.getConnection();
265	                PreparedStatement select = connection.prepareStatement(
266	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
267	            select.setLong(1, id);
268	            try (ResultSet rows = select.executeQuery()) {
269	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
270	            }
271	        } catch (SQLException failure) {
272	            throw new IllegalStateException("could not read reservation " + id, failure);
273	        }
274	    }
275	
276	    public List<Reservation> all() {
277	        try (Connection connection = dataSource.getConnection();
278	                PreparedStatement select = connection.prepareStatement(
279	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
280	                ResultSet rows = select.executeQuery()) {
281	            List<Reservation> reservations = new ArrayList<>();
282	            while (rows.next()) {
283	                reservations.add(read(rows));
284	            }
285	            return reservations;
286	        } catch (SQLException failure) {
287	            throw new IllegalStateException("could not read the reservations", failure);
288	        }
289	    }
290	
291	    private static Reservation read(ResultSet row) throws SQLException {
292	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"));
293	        NewReservation request = new NewReservation(
294	                row.getInt("room_number"),
295	                guest,
296	                row.getDate("check_in").toLocalDate(),
297	                row.getDate("check_out").toLocalDate(),
298	                row.getInt("guests"),
299	                RatePlan.valueOf(row.getString("rate_plan")));
300	        Price price = new Price(
301	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
302	                row.getBigDecimal("total"));
303	        return new Reservation(
304	                row.getLong("id"),
305	                request,
306	                price,
307	                ReservationStatus.valueOf(row.getString("status")),
308	                row.getBigDecimal("amount_paid"),
309	                row.getBigDecimal("refund"));
310	    }
311	}
